// Valida evento vindo do BACKEND (HMAC + janela de tempo)
const crypto = require('crypto');
const h = $input.item.json.headers || {};
const ts = h['x-airflow-timestamp'];
const sig = h['x-airflow-signature'];
const body = JSON.stringify($input.item.json.body);
if (!ts || !sig) throw new Error('Assinatura ausente');
if (Math.abs(Date.now()/1000 - Number(ts)) > 300) throw new Error('Timestamp fora da janela');
const esperado = crypto.createHmac('sha256', $env.N8N_WEBHOOK_SECRET).update(ts + '.' + body).digest('hex');
if (esperado !== sig) throw new Error('Assinatura invalida');
return { json: $input.item.json.body };

// Encaminha transicao ao backend — a validacao REAL e da maquina de estados
const crypto = require('crypto');
const b = $json.body || $json;
const permitidos = ['ordem.agendar','ordem.iniciar','ordem.solicitar_conclusao','ordem.confirmar_conclusao'];
if (!permitidos.includes(b.command)) throw new Error('Comando nao permitido neste workflow');
return { json: { comando: { ...b, idempotency_key: b.idempotency_key || crypto.randomUUID() } } };

// Assina comando para o BACKEND (HMAC + timestamp + nonce anti-replay)
const crypto = require('crypto');
const payload = $json.comando;
const body = JSON.stringify(payload);
const ts = String(Math.floor(Date.now()/1000));
const nonce = crypto.randomUUID();
const sig = crypto.createHmac('sha256', $env.BACKEND_WEBHOOK_SECRET).update(ts + '.' + nonce + '.' + body).digest('hex');
return { json: { body, ts, nonce, sig } };
